(function () {
  'use strict';
  // Roth (after-tax) or pre-tax deferral, with the same take-home-pay budget b each year.
  //   A. Roth: deferral = min(b, limit); any rest goes to a taxable brokerage account.
  //   B. Pre-tax, grossed up: deferral = min(b / (1 - tax now), limit), which costs deferral x (1 - tax now)
  //      of take-home pay; any rest of the budget goes to the brokerage account.
  //   C. Pre-tax, same dollars: deferral = min(b, limit); the tax saving plus any rest goes to brokerage.
  //   All deposits at the start of the year; plan accounts grow at r. Brokerage: dividends (yield x value)
  //   are taxed yearly and reinvested (added to basis); the rest of the return is unrealized gain, taxed
  //   at the capital gains rate when sold. After tax = Roth + pre-tax x (1 - retirement rate) + brokerage
  //   value - gains tax on (value - basis).
  //   Break-even rate for A vs B: 1 - (A - B's brokerage) / B's pre-tax balance.
  // Checked in Node (fake DOM, whole script, tests/rpa.test.js): $10,000 budget, 24% now and later,
  //   no taxable-account taxes -> A, B and C all equal (B defers $13,157.89 = 10,000 / 0.76);
  //   $10,000 at 6% for 30 years, start of year = $838,017 Roth; with the limit binding ($20,000 at
  //   24% wants $26,316 pre-tax, capped at $24,500, so $1,380 goes to brokerage); brokerage with 0% yield
  //   and 15% gains tax: $1,000 a year at 6% for 10 years = $13,971.64, less 15% of the $3,971.64 gain =
  //   $13,375.89; budget at the limit, equal tax rates and 15% gains tax -> Roth ahead (the textbook limit effect).
  //
  // ---- 2026 ELECTIVE DEFERRAL LIMITS (tax year 2026) ------------------------------------------------
  // IRS Notice 2025-67: 401(k)/403(b)/governmental 457(b) limit $24,500; age-50 catch-up $8,000;
  // age 60-63 catch-up $11,250. Held at 2026 levels for later years.
  var LIMITS = { year: 2026, deferral: 24500, catchUp50: 8000, catchUp60to63: 11250 };
  // ------------------------------------------------------------------------------------------------

  function limitFor(age) {
    if (age >= 60 && age <= 63) return LIMITS.deferral + LIMITS.catchUp60to63;
    return LIMITS.deferral + (age >= 50 ? LIMITS.catchUp50 : 0);
  }
  function Brokerage() { this.value = 0; this.basis = 0; }
  Brokerage.prototype.add = function (x) { this.value += x; this.basis += x; };
  Brokerage.prototype.grow = function (rate, yieldRate, divTax) {
    var div = this.value * yieldRate, afterDiv = div * (1 - divTax);
    this.value += this.value * (rate - yieldRate) + afterDiv;
    this.basis += afterDiv;
  };
  Brokerage.prototype.afterTax = function (gainTax) { return this.value - Math.max(0, this.value - this.basis) * gainTax; };

  // p: age, retireAge, budget, taxNow, taxLater, rate, yieldRate, divTax, gainTax (decimals)
  function compare(p) {
    var rothA = 0, preB = 0, preC = 0, bkA = new Brokerage(), bkB = new Brokerage(), bkC = new Brokerage(), rows = [];
    var keep = 1 - p.taxNow;
    for (var y = 0; y < p.retireAge - p.age; y++) {
      var lim = limitFor(p.age + y);
      var dA = Math.min(p.budget, lim);
      var dB = keep > 0 ? Math.min(p.budget / keep, lim) : lim;
      var dC = Math.min(p.budget, lim);
      rothA += dA; bkA.add(p.budget - dA);
      preB += dB; bkB.add(Math.max(0, p.budget - dB * keep));
      preC += dC; bkC.add(p.budget - dC * keep);
      rothA *= 1 + p.rate; preB *= 1 + p.rate; preC *= 1 + p.rate;
      [bkA, bkB, bkC].forEach(function (b) { b.grow(p.rate, p.yieldRate, p.divTax); });
      rows.push({ age: p.age + y, lim: lim, dA: dA, dB: dB, dC: dC,
                  a: rothA + bkA.afterTax(p.gainTax), b: preB * (1 - p.taxLater) + bkB.afterTax(p.gainTax),
                  c: preC * (1 - p.taxLater) + bkC.afterTax(p.gainTax) });
    }
    var last = rows[rows.length - 1], bB = bkB.afterTax(p.gainTax);
    return { rows: rows, last: last, rothA: rothA, preB: preB, preC: preC,
             bkA: bkA.afterTax(p.gainTax), bkB: bB, bkC: bkC.afterTax(p.gainTax),
             breakEven: preB > 0 ? 1 - (last.a - bB) / preB : NaN };
  }

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });
  function fmt(x) { return money.format(Math.abs(x) < 0.5 ? 0 : x); }
  function pct(x) { return (Math.round(x * 1000) / 10) + '%'; }
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, t) { document.getElementById(id).textContent = t; }

  function update() {
    var budget = num('rpaBudget'), age = num('rpaAge'), retireAge = num('rpaRetireAge'), taxNow = num('rpaTaxNow'),
        taxLater = num('rpaTaxLater'), rate = num('rpaRate'), yieldRate = num('rpaYield'), divTax = num('rpaDivTax'),
        gainTax = num('rpaGainTax');
    var error = document.getElementById('rpaError');
    var bad = [budget, age, retireAge, taxNow, taxLater, rate, yieldRate, divTax, gainTax].some(isNaN) || budget <= 0 ||
              age !== Math.round(age) || retireAge !== Math.round(retireAge) || age < 16 || age > 99 || retireAge <= age ||
              retireAge > 100 || taxNow < 0 || taxNow > 70 || taxLater < 0 || taxLater > 70 || rate < -20 || rate > 30 ||
              yieldRate < 0 || yieldRate > 20 || divTax < 0 || divTax > 70 || gainTax < 0 || gainTax > 70;
    error.hidden = !bad;
    if (bad) {
      error.textContent = 'Enter a yearly amount above $0, whole-number ages from 16 to 99 with retirement later (up to 100), ' +
                          'tax rates up to 70%, a return from -20 to 30% and a dividend yield up to 20%.';
      return;
    }
    var r = compare({ age: age, retireAge: retireAge, budget: budget, taxNow: taxNow / 100, taxLater: taxLater / 100,
                      rate: rate / 100, yieldRate: yieldRate / 100, divTax: divTax / 100, gainTax: gainTax / 100 });
    var opts = [['A. Roth', r.last.a], ['B. Larger pre-tax', r.last.b], ['C. Pre-tax + brokerage', r.last.c]]
      .sort(function (x, y) { return y[1] - x[1]; });
    set('rpaBest', opts[0][1] - opts[1][1] < 0.5 ? 'About even' : opts[0][0]);
    set('rpaRothTotal', fmt(r.last.a));
    set('rpaGrossTotal', fmt(r.last.b));
    set('rpaSideTotal', fmt(r.last.c));
    set('rpaAgeLabel', 'At age ' + retireAge + ', if you cashed everything out.');
    var first = r.rows[0], keep = 1 - taxNow / 100;
    set('rpaYrA', fmt(first.dA) + (budget > first.dA ? ' + ' + fmt(budget - first.dA) + ' to brokerage' : ''));
    set('rpaYrB', fmt(first.dB) + (budget - first.dB * keep >= 0.5 ? ' + ' + fmt(budget - first.dB * keep) + ' to brokerage' : ''));
    set('rpaYrC', fmt(first.dC) + ' + ' + fmt(budget - first.dC * keep) + ' to brokerage');
    set('rpaLimit', fmt(first.lim));
    set('rpaEndA', fmt(r.rothA) + ' / ' + fmt(r.bkA));
    set('rpaEndB', fmt(r.preB) + ' / ' + fmt(r.bkB));
    set('rpaEndC', fmt(r.preC) + ' / ' + fmt(r.bkC));
    set('rpaBreakEven', isFinite(r.breakEven) ? (r.breakEven <= 0 ? 'Any rate' : r.breakEven >= 1 ? 'Never' : pct(r.breakEven)) : '–');
    var body = document.getElementById('rpaSchedule');
    body.textContent = '';
    r.rows.forEach(function (x) {
      var tr = document.createElement('tr');
      [x.age, fmt(x.lim), fmt(x.dA), fmt(x.dB), fmt(x.a), fmt(x.b), fmt(x.c)].forEach(function (v) {
        var td = document.createElement('td'); td.textContent = v; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rpaForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
